mkdir -p <tmp>/stress && cat > <tmp>/stress/stress.py <<'EOF'
import sys, threading, random
sys.path.insert(0, "<workspace>")
sys.setswitchinterval(1e-6)
from ttlcache import TTLCache
from tests.support import FakeClock

bad = 0
for round_ in range(200):
    clock = FakeClock()
    calls = {}
    lk = threading.Lock()
    def loader(key):
        with lk:
            calls[key] = calls.get(key, 0) + 1
        if random.random() < 0.3:
            raise ValueError("x")
        return (key, calls[key])
    cache = TTLCache(loader, ttl=5, clock=clock)
    errs = []
    def work():
        for i in range(200):
            k = random.randrange(3)
            if random.random() < 0.05:
                cache.invalidate(k)
            if random.random() < 0.05:
                clock.advance(1)
            try:
                v = cache.get(k)
                # a served value must not be expired at the time of return: value stamp check is internal
            except ValueError:
                pass
            except Exception as e:
                errs.append(repr(e))
    ts = [threading.Thread(target=work) for _ in range(8)]
    [t.start() for t in ts]; [t.join(60) for t in ts]
    s = cache.stats()
    if errs or any(t.is_alive() for t in ts) or s["hits"] + s["misses"] != 8 * 200 or s["loads"] != sum(calls.values()) or s["failures"] > s["loads"]:
        bad += 1
        print("BAD", s, errs[:2])
print("bad rounds:", bad)
EOF
cd <tmp> && timeout 500 python -I <tmp>/stress/stress.py
